let menu = []
let basket = []

fetch('/api/menu')
  .then((response) => response.json())
  .then((data) => {
    menu = data
    renderMenu(menu)
  })

function getTotal() {
  return basket.reduce((sum, item) => sum + item.price, 0)
}

